import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.Random;

/**
 * Headless replica of the Simulator's deterministic core, used to verify that
 * refactoring preserves runtime behavior. Mirrors populate() and simulateOneStep()
 * and prints a per-step fingerprint of the field.
 */
public class RegressionHarness
{
    private static final int DEPTH = 80;
    private static final int WIDTH = 120;
    private static final double HIPPOPOTAMUS_CREATION_PROBABILITY = 0.01;
    private static final double LEOPARD_CREATION_PROBABILITY = 0.03;
    private static final double BEAR_CREATION_PROBABILITY = 0.03;
    private static final double MONKEY_CREATION_PROBABILITY = 0.08;
    private static final double SLOTH_CREATION_PROBABILITY = 0.08;
    private static final double PLANT_CREATION_PROBABILITY = 0.13;

    public static void main(String[] args)
    {
        int steps = args.length > 0 ? Integer.parseInt(args[0]) : 400;
        Randomizer.reset();
        Weather weather = Weather.getWeather();
        weather.resetWeather();

        Field field = new Field(DEPTH, WIDTH);
        List<Organism> organisms = new ArrayList<>();
        populate(field, organisms);

        int step = 0;
        System.out.println(step + ":" + fingerprint(field));
        for (int s = 1; s <= steps; s++) {
            step++;
            if (step % 450 == 0) {
                weather.changeWeather();
            }
            Nursery nursery = new Nursery();
            for (Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
                Organism organism = it.next();
                if (organism.getIsDiurnal() && step % 80 <= 55) {
                    organism.act(nursery);
                }
                else if (!organism.getIsDiurnal() && step % 80 > 55) {
                    organism.act(nursery);
                }
                if (!organism.isAlive()) {
                    it.remove();
                }
            }
            organisms.addAll(nursery.getNewborns());
            System.out.println(step + ":" + fingerprint(field));
        }
    }

    private static void populate(Field field, List<Organism> organisms)
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= HIPPOPOTAMUS_CREATION_PROBABILITY) {
                    organisms.add(new Hippopotamus(true, field, new Location(row, col)));
                }
                else if (rand.nextDouble() <= LEOPARD_CREATION_PROBABILITY) {
                    organisms.add(new Leopard(true, field, new Location(row, col)));
                }
                else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                    organisms.add(new Bear(true, field, new Location(row, col)));
                }
                else if (rand.nextDouble() <= MONKEY_CREATION_PROBABILITY) {
                    organisms.add(new Monkey(true, field, new Location(row, col)));
                }
                if (rand.nextDouble() <= SLOTH_CREATION_PROBABILITY) {
                    organisms.add(new Sloth(true, field, new Location(row, col)));
                }
                else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    organisms.add(new Plant(true, field, new Location(row, col)));
                }
            }
        }
    }

    private static String fingerprint(Field field)
    {
        int[] counts = new int[128];
        long checksum = 0;
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object o = field.getObjectAt(row, col);
                if (o != null) {
                    char code = o.getClass().getSimpleName().charAt(0);
                    counts[code]++;
                    checksum = checksum * 31 + (long) code * (row * WIDTH + col + 1);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (char c : new char[] {'H', 'L', 'B', 'M', 'S', 'P'}) {
            sb.append(c).append('=').append(counts[c]).append(' ');
        }
        sb.append("chk=").append(checksum);
        return sb.toString();
    }
}

